using System.Text;

namespace Bequadro.Cli;

/// <summary>
/// Writes generated files to the output directory, or compares them with it (CLI-005).
/// </summary>
/// <remarks>
/// Symbolic links below the output directory are never followed, changed or deleted, so a run can't reach outside it
/// (CLI-007). Entries whose names start with <c>.</c> are never deleted: generated names never do, and the temporary
/// files of a run in progress do.
/// </remarks>
internal static class OutputDirectory
{
    /// <summary>
    /// The comment every generated file starts with, without the comment syntax.
    /// </summary>
    public const string GeneratedComment = "Code generated by Bequadro. DO NOT EDIT.";

    private static readonly byte[][] GeneratedFirstLines =
    [
        Encoding.UTF8.GetBytes("// " + GeneratedComment),
        Encoding.UTF8.GetBytes("# " + GeneratedComment),
    ];

    private static readonly UTF8Encoding Utf8 = new(encoderShouldEmitUTF8Identifier: false);

    private static readonly EnumerationOptions AllEntries = new() { AttributesToSkip = 0, IgnoreInaccessible = false };

    private enum EntryKind
    {
        None,
        File,
        Directory,
        Link,
    }

    /// <summary>
    /// Makes the output directory hold exactly <paramref name="files"/> among the generated files under it. Returns
    /// the number of files created, changed or deleted, which with <paramref name="check"/> are only listed.
    /// </summary>
    /// <param name="directory">The full path of the output directory.</param>
    /// <param name="displayDirectory">The output directory as the command line gave it, for messages.</param>
    /// <param name="files">The files to generate, with paths relative to the output directory.</param>
    /// <param name="check">Whether to list the changes instead of making them.</param>
    /// <param name="output">Where the changes are listed.</param>
    public static int Apply(
        string directory,
        string displayDirectory,
        IReadOnlyList<GeneratedFile> files,
        bool check,
        TextWriter output
    )
    {
        directory = Path.TrimEndingDirectorySeparator(directory);
        string Display(string path) => Path.Join(displayDirectory, Path.GetRelativePath(directory, path));
        string Relative(string path) => Path.GetRelativePath(directory, path);

        if (File.Exists(directory))
        {
            throw new UsageException($"The output directory '{displayDirectory}' is a file.");
        }

        var planned = files.ToDictionary(
            f => Path.GetFullPath(Path.Combine(directory, f.Path)),
            f => f,
            StringComparer.Ordinal
        );

        // Everything is checked before anything is written, so a run that can't complete writes nothing
        var existing = new Dictionary<string, byte[]>(StringComparer.Ordinal);
        foreach (var path in planned.Keys.Order(StringComparer.Ordinal))
        {
            CheckParents(directory, path, Relative);
            switch (FileErrors.Guard("read", Display(path), () => Kind(path)))
            {
                case EntryKind.Link:
                    throw new UsageException(
                        $"'{Relative(path)}' in the output directory is a symbolic link; nothing was written."
                    );
                case EntryKind.Directory:
                    throw new UsageException(
                        $"'{Relative(path)}' in the output directory is a directory, where a file would be generated; nothing was written."
                    );
                case EntryKind.File:
                    // Decided from the file itself, not from a listing of the directory, which another run that is
                    // replacing the file could make miss it
                    if (ReadIfPresent(path, Display(path)) is { } content)
                    {
                        if (!IsGenerated(content))
                        {
                            throw new UsageException(
                                $"'{Relative(path)}' in the output directory exists and wasn't generated by Bequadro; nothing was written."
                            );
                        }

                        existing[path] = content;
                    }

                    break;
            }
        }

        var changes = new List<(string Action, string Path)>();
        foreach (var (path, file) in planned.OrderBy(p => p.Key, StringComparer.Ordinal))
        {
            if (!existing.TryGetValue(path, out var content))
            {
                changes.Add(("create", path));
            }
            else if (!content.AsSpan().SequenceEqual(Utf8.GetBytes(file.Content)))
            {
                changes.Add(("update", path));
            }
        }

        if (Directory.Exists(directory))
        {
            changes.AddRange(
                GeneratedFiles(directory, Display)
                    .Where(path => !planned.ContainsKey(path))
                    .Order(StringComparer.Ordinal)
                    .Select(path => ("delete", path))
            );
        }

        if (check)
        {
            foreach (var (action, path) in changes)
            {
                output.WriteLine($"would {action} {Relative(path)}");
            }

            return changes.Count;
        }

        foreach (var (action, path) in changes)
        {
            if (action == "delete")
            {
                FileErrors.Guard("delete", Display(path), () => File.Delete(path));
                RemoveEmptyDirectories(Path.GetDirectoryName(path)!, directory);
            }
            else
            {
                WriteAtomically(path, planned[path].Content, Display);
            }
        }

        return changes.Count;
    }

    /// <summary>
    /// Checks that the directories a planned file goes in, below the output directory, are directories or don't exist
    /// yet.
    /// </summary>
    private static void CheckParents(string root, string path, Func<string, string> relative)
    {
        var parents = new List<string>();
        for (var parent = Path.GetDirectoryName(path); parent is not null && parent.Length > root.Length; )
        {
            parents.Add(parent);
            parent = Path.GetDirectoryName(parent);
        }

        parents.Reverse();
        foreach (var parent in parents)
        {
            switch (Kind(parent))
            {
                case EntryKind.None:
                    // Nor anything below it
                    return;
                case EntryKind.Link:
                    throw new UsageException(
                        $"'{relative(parent)}' in the output directory is a symbolic link; nothing was written."
                    );
                case EntryKind.File:
                    throw new UsageException(
                        $"'{relative(parent)}' in the output directory is a file, where a directory would be generated; nothing was written."
                    );
            }
        }
    }

    private static EntryKind Kind(string path)
    {
        var info = new FileInfo(path);
        if (info.LinkTarget is not null)
        {
            return EntryKind.Link;
        }

        return Directory.Exists(path) ? EntryKind.Directory
            : info.Exists ? EntryKind.File
            : EntryKind.None;
    }

    /// <summary>
    /// A file's content, or null if it no longer exists.
    /// </summary>
    private static byte[]? ReadIfPresent(string path, string displayPath)
    {
        try
        {
            return FileErrors.Guard("read", displayPath, () => File.ReadAllBytes(path));
        }
        catch (UsageException exception) when (exception.InnerException is FileNotFoundException)
        {
            return null;
        }
    }

    /// <summary>
    /// The files under the output directory whose first line is the generated comment, without following symbolic
    /// links or entering entries whose names start with <c>.</c>.
    /// </summary>
    private static List<string> GeneratedFiles(string root, Func<string, string> display)
    {
        var generated = new List<string>();
        var pending = new Stack<DirectoryInfo>([new DirectoryInfo(root)]);
        while (pending.TryPop(out var directory))
        {
            var entries = FileErrors.Guard("read", display(directory.FullName), () =>
                directory.EnumerateFileSystemInfos("*", AllEntries).ToList()
            );
            foreach (var entry in entries)
            {
                if (entry.Name.StartsWith('.') || entry.LinkTarget is not null)
                {
                    continue;
                }

                if (entry is DirectoryInfo child)
                {
                    pending.Push(child);
                }
                else if (StartsWithGeneratedComment(entry.FullName))
                {
                    generated.Add(entry.FullName);
                }
            }
        }

        return generated;
    }

    /// <summary>
    /// Whether a file's first line is the generated comment. A file that can't be read isn't treated as generated,
    /// so it is left alone.
    /// </summary>
    private static bool StartsWithGeneratedComment(string path)
    {
        try
        {
            using var stream = new FileStream(
                path,
                FileMode.Open,
                FileAccess.Read,
                FileShare.ReadWrite | FileShare.Delete
            );
            var buffer = new byte[3 + GeneratedFirstLines.Max(l => l.Length) + 2];
            var read = stream.ReadAtLeast(buffer, buffer.Length, throwOnEndOfStream: false);
            return IsGenerated(buffer.AsSpan(0, read));
        }
        catch (Exception exception) when (exception is IOException or UnauthorizedAccessException)
        {
            return false;
        }
    }

    /// <summary>
    /// Whether text starts with a line that is exactly the generated comment, after an optional byte order mark.
    /// </summary>
    private static bool IsGenerated(ReadOnlySpan<byte> content)
    {
        if (content.StartsWith(Encoding.UTF8.Preamble))
        {
            content = content[Encoding.UTF8.Preamble.Length..];
        }

        foreach (var line in GeneratedFirstLines)
        {
            if (content.StartsWith(line))
            {
                var rest = content[line.Length..];
                return rest.IsEmpty || rest[0] == (byte)'\n' || rest.StartsWith("\r\n"u8);
            }
        }

        return false;
    }

    /// <summary>
    /// Replaces a file through a temporary file in the same directory, so readers never see a partial file. The
    /// temporary file's name starts with <c>.</c>, so another run never deletes it as a stale generated file.
    /// </summary>
    private static void WriteAtomically(string path, string content, Func<string, string> display)
    {
        var directory = Path.GetDirectoryName(path)!;
        FileErrors.Guard("create", display(directory), () => Directory.CreateDirectory(directory));
        var temporary = Path.Combine(directory, $".{Path.GetFileName(path)}.{Guid.NewGuid():N}.tmp");
        try
        {
            FileErrors.Guard("write", display(path), () => File.WriteAllText(temporary, content, Utf8));
            FileErrors.Guard("write", display(path), () => File.Move(temporary, path, overwrite: true));
        }
        finally
        {
            try
            {
                File.Delete(temporary);
            }
            catch (Exception exception) when (exception is IOException or UnauthorizedAccessException)
            {
                // The error that matters has already been reported
            }
        }
    }

    /// <summary>
    /// Removes the directories that deleting a file left empty, up to the output directory. Another run may be
    /// writing into one at the same time, so a directory that is no longer empty, or already gone, ends the climb.
    /// </summary>
    private static void RemoveEmptyDirectories(string directory, string root)
    {
        var current = Path.GetFullPath(directory);
        try
        {
            while (
                current.Length > root.Length
                && current.StartsWith(root, StringComparison.Ordinal)
                && !Directory.EnumerateFileSystemEntries(current).Any()
            )
            {
                Directory.Delete(current);
                current = Path.GetDirectoryName(current)!;
            }
        }
        catch (Exception exception) when (exception is IOException or UnauthorizedAccessException)
        {
            // Left for the next run
        }
    }
}
